import type { Readable } from 'node:stream';

export interface PutOptions {
  contentType: string;
}

/**
 * Where attachment bytes live. Keys are generated by testRex (`org/<orgId>/attachments/<id>`),
 * never derived from user input such as file names.
 */
export interface StorageAdapter {
  readonly driver: 'local' | 's3';
  /** Stores the stream under `key`, replacing any existing object. */
  put(key: string, body: Readable, options: PutOptions): Promise<void>;
  /** Throws {@link StorageNotFoundError} when the object does not exist. */
  get(key: string): Promise<Readable>;
  /** Succeeds when the object does not exist. */
  delete(key: string): Promise<void>;
  /** Writes, reads back and deletes a probe object; throws a descriptive error on failure. */
  check(): Promise<void>;
}

export class StorageNotFoundError extends Error {
  constructor(readonly key: string) {
    super(`Stored object not found: ${key}`);
    this.name = 'StorageNotFoundError';
  }
}

const KEY_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*(\/[A-Za-z0-9][A-Za-z0-9._-]*)*$/;

/** Rejects keys that could escape the storage root (`..`, absolute paths, backslashes). */
export function assertValidKey(key: string): void {
  if (!KEY_PATTERN.test(key) || key.split('/').some((part) => part === '..' || part === '.')) {
    throw new Error(`Invalid storage key: ${JSON.stringify(key)}`);
  }
}

/** Storage key of an attachment; organizations never share a prefix. */
export function attachmentStorageKey(organizationId: string, attachmentId: string): string {
  return `org/${organizationId}/attachments/${attachmentId}`;
}

/** Readiness probes write here; never collides with `org/...` keys. */
export const PROBE_PREFIX = 'probe';
